su_kien.raw:
{
  "title": "Tính diện tích elip giao tuyến của mặt phẳng và hình trụ",
  "description": "Chương trình này dựng hình trụ và mặt phẳng, sau đó tìm giao tuyến là một elip và tính diện tích của nó.",
  "memory_declarations": [
    {
      "name": "O",
      "type": "point3",
      "initial_value": [0, 0, 0],
      "source_fact_id": "tam_day_duoi_O",
      "model_assumption": "Đặt tâm đáy dưới của hình trụ tại gốc tọa độ O(0,0,0) của hệ trục Oxyz."
    },
    {
      "name": "O_prime",
      "type": "point3",
      "initial_value": [0, 0, 20],
      "source_fact_id": "tam_day_tren_O_prime"
    },
    {
      "name": "ban_kinh_day",
      "type": "float",
      "initial_value": 4.0,
      "source_fact_id": "ban_kinh_day"
    },
    {
      "name": "E",
      "type": "ellipse3",
      "source_fact_id": "giao_tuyen_elip"
    },
    {
      "name": "dien_tich_e",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "construct_curved_solid",
      "target_var": "hinh_tru",
      "curved_kind": "cylinder",
      "anchor": "O",
      "apex_or_top": "O_prime",
      "radius": "ban_kinh_day",
      "label": "Hình trụ tròn xoay"
    },
    {
      "kind": "construct_plane_from_equation",
      "target_var": "mat_phang_alpha_obj",
      "a": 2,
      "b": 0,
      "c": -1,
      "d": 10,
      "source_fact_id": "mat_phang_alpha",
      "label": "Mặt phẳng (α)"
    },
    {
      "kind": "assign",
      "target_var": "E",
      "expr": {
        "kind": "intersect_plane_curved_ellipse",
        "solid": "hinh_tru",
        "plane": "mat_phang_alpha_obj"
      }
    },
    {
      "kind": "assign",
      "target_var": "dien_tich_e",
      "expr": {
        "kind": "measure",
        "quantity": "area",
        "of": "E"
      }
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách dựng hình trụ, mặt phẳng và tìm giao tuyến là một elip, sau đó tính diện tích của elip đó."
}

